            CR = max(self.CR_range[0], CR - 0.1 * (CR - self.CR_range[0]))
        return F, CR

    def dynamic_clustering(self, population, evals):
        num_clusters = max(2, min(self.population_size // 20, 5 * (1 - evals / self.budget)))
        kmeans = MiniBatchKMeans(n_clusters=int(num_clusters), batch_size=self.population_size)
        labels = kmeans.fit_predict(population)
        return labels

    def __call__(self, func):
        self.bounds = func.bounds
        population = self.initialize_population()
        scores = np.array([func(ind) for ind in population])
